namespace FormSubmission.AdminPortal.Services; public class AuthStateService { public string? Token {get;private set;} public string? Username {get;private set;} public string? Role {get;private set;} public bool IsLoggedIn=>!string.IsNullOrWhiteSpace(Token); public void SetLogin(string token,string username,string role){Token=token;Username=username;Role=role;} public void Logout(){Token=null;Username=null;Role=null;} }